package com.lamggm.rospocket;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import java.util.*;import java.nio.charset.StandardCharsets;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class ReadoutPresentationTest {
 static DashboardLayout precision(int n)throws Exception{JSONObject j=new JSONObject(DashboardLayout.defaults().display("watch0",new DashboardLayout.Display("gauge","data",-1,1,"m")).encode()).put("schema",5);JSONArray cards=j.getJSONArray("cards");for(int i=0;i<cards.length();i++)if(cards.getJSONObject(i).has("display"))cards.getJSONObject(i).getJSONObject("display").put("decimals",n);return DashboardLayout.decode(j.toString());}
 static BenchProfiles.Profile profile(){List<BenchProfiles.Watch> ws=new ArrayList<>();ws.add(new BenchProfiles.Watch("rt/value","std_msgs::msg::dds_::Float64_",false,false));for(int i=1;i<4;i++)ws.add(new BenchProfiles.Watch("","",false,false));return new BenchProfiles.Profile("01234567-0123-4567-89ab-0123456789ab","Robot",98,"192.0.2.1",ws,Arrays.asList(new BenchProfiles.Series(0,"data")));}
 static JSONObject future()throws Exception{JSONObject j=new JSONObject(new String(BenchProfiles.exportProfile(profile()),StandardCharsets.UTF_8)).put("schema",7);j.getJSONObject("profile").put("robot",JSONObject.NULL);j.getJSONObject("profile").getJSONArray("plots").getJSONObject(0).put("unit","m/s");return j;}
 @Test public void precisionRoundTripsInPortableProfileAndLayout()throws Exception{DashboardLayout d=precision(3);assertEquals(5,new JSONObject(d.encode()).getInt("schema"));assertEquals(3,new JSONObject(d.encode()).getJSONArray("cards").getJSONObject(0).getJSONObject("display").getInt("decimals"));assertEquals(d.encode(),BenchProfiles.importProfile(BenchProfiles.exportProfile(profile().withDashboard(d))).dashboard.encode());}
 @Test public void numericPrecisionRoundsPresentationButKeepsRawValueAndStaleIsNeverZero()throws Exception{DashboardLayout d=precision(3);MetricCard c=new MetricCard(RuntimeEnvironment.getApplication());c.display(d.get("watch0").display);c.bind(0,1,"rt/value","std_msgs::msg::dds_::Float64_","Recebendo","not the data",true);c.sample(new JSONArray().put(new JSONObject().put("path","data").put("value",-2.3391e-7).put("state","finite")),true);assertTrue(c.getContentDescription().toString(),c.getContentDescription().toString().contains("0.000 m"));java.lang.reflect.Field raw=MetricCard.class.getDeclaredField("numeric");raw.setAccessible(true);assertEquals(-2.3391e-7,(Double)raw.get(c),0);c.sample(null,false);assertNull(raw.get(c));assertTrue(c.getContentDescription().toString().contains("Sem dados atuais"));}
 @Test public void explicitSeriesUnitSurvivesImportAndExport()throws Exception{BenchProfiles.Profile p=BenchProfiles.importProfile(future().toString().getBytes(StandardCharsets.UTF_8));JSONObject out=new JSONObject(new String(BenchProfiles.exportProfile(p),StandardCharsets.UTF_8));assertEquals("m/s",out.getJSONObject("profile").getJSONArray("plots").getJSONObject(0).getString("unit"));}
 @Test public void knownRobotNeedsExactSavedAssociationAndConnectionNotNameOrAddressAlone()throws Exception{JSONObject j=future();String hash="0123456789abcdef".repeat(4);j.getJSONObject("profile").put("robot",new JSONObject().put("wire","rt/robot_description").put("fingerprint",hash));BenchProfiles.Profile p=BenchProfiles.importProfile(j.toString().getBytes(StandardCharsets.UTF_8));BenchProfiles b=new BenchProfiles().save(p);java.lang.reflect.Method recognize=BenchProfiles.class.getDeclaredMethod("recognize",int.class,String.class,String.class,String.class,String.class,String.class);recognize.setAccessible(true);Object[] args={98,"192.0.2.1","jazzy","lan","rt/robot_description",hash};assertSame(p,recognize.invoke(b,args));args[5]="f".repeat(64);assertNull(recognize.invoke(b,args));args[5]=hash;args[0]=97;assertNull(recognize.invoke(b,args));args[0]=98;BenchProfiles.Profile twin=BenchProfiles.importProfile(BenchProfiles.exportProfile(p)).rename("Same robot other dashboard");assertNull("Two matching profiles must never be guessed",recognize.invoke(b.save(twin),args));assertEquals(p.id,((BenchProfiles.Profile)recognize.invoke(BenchProfiles.decode(b.encode()),args)).id);assertEquals(hash,new JSONObject(new String(BenchProfiles.exportProfile(p.withDashboard(DashboardLayout.defaults()).rename("Renamed")),StandardCharsets.UTF_8)).getJSONObject("profile").getJSONObject("robot").getString("fingerprint"));}
 @Test public void malformedNewPrecisionAndUnitsAreRejectedNotNormalized()throws Exception{for(int n:new int[]{-2,9})assertThrows(IllegalArgumentException.class,()->precision(n));JSONObject j=future();j.getJSONObject("profile").getJSONArray("plots").getJSONObject(0).put("unit","m\ns");assertThrows(IllegalArgumentException.class,()->BenchProfiles.importProfile(j.toString().getBytes(StandardCharsets.UTF_8)));}
}
